import React from 'react';
import { Link } from 'react-router-dom';
import { useComparison } from '../../context/ComparisonContext';

const formatPrice = (value) => new Intl.NumberFormat('pt-PT', {
  style: 'currency',
  currency: 'EUR',
  maximumFractionDigits: 0,
}).format(value || 0);

export default function Comparador() {
  const { items, remover, limpar } = useComparison();

  if (items.length === 0) {
    return (
      <main className="min-h-[calc(100vh-72px)] bg-slate-50 px-5 py-16 text-slate-950 transition-colors dark:bg-slate-950 dark:text-slate-100">
        <div className="mx-auto max-w-3xl rounded-3xl border border-slate-200 bg-white p-10 text-center shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <span className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-teal-50 text-teal-700 dark:bg-teal-400/10 dark:text-teal-300" aria-hidden="true">
            <svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
              <path d="M8 3 4 7l4 4" /><path d="M4 7h16" /><path d="m16 21 4-4-4-4" /><path d="M20 17H4" />
            </svg>
          </span>
          <h1 className="mt-6 text-2xl font-black tracking-tight sm:text-3xl">Ainda não existem anúncios para comparar</h1>
          <p className="mx-auto mt-3 max-w-xl text-sm leading-7 text-slate-600 dark:text-slate-400">
            Abre um anúncio e utiliza “Adicionar à comparação”. Podes analisar até três opções lado a lado sem criar conta e sem enviar estes dados para a base de dados.
          </p>
          <div className="mt-7 flex flex-col justify-center gap-3 sm:flex-row">
            <Link to="/carros" className="rounded-xl bg-slate-950 px-5 py-3 text-sm font-extrabold text-white no-underline transition hover:bg-slate-800 dark:bg-teal-400 dark:text-slate-950 dark:hover:bg-teal-300">Explorar Drive</Link>
            <Link to="/imoveis" className="rounded-xl border border-slate-300 bg-white px-5 py-3 text-sm font-extrabold text-slate-800 no-underline transition hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100 dark:hover:bg-slate-800">Explorar Estate</Link>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-[calc(100vh-72px)] bg-slate-50 px-4 py-10 text-slate-950 transition-colors sm:px-6 dark:bg-slate-950 dark:text-slate-100">
      <div className="mx-auto max-w-7xl">
        <header className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <span className="text-xs font-black uppercase tracking-[0.16em] text-teal-700 dark:text-teal-300">Decisão informada</span>
            <h1 className="mt-2 text-3xl font-black tracking-tight sm:text-4xl">Comparador de anúncios</h1>
            <p className="mt-2 text-sm text-slate-600 dark:text-slate-400">{items.length} de 3 opções guardadas apenas neste navegador.</p>
          </div>
          <button type="button" onClick={limpar} className="self-start rounded-xl border border-slate-300 bg-white px-4 py-2.5 text-xs font-extrabold text-slate-700 transition hover:bg-slate-100 sm:self-auto dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:bg-slate-800">
            Limpar comparação
          </button>
        </header>

        <div className="overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-sm dark:border-slate-800 dark:bg-slate-900">
          <table className="w-full min-w-[760px] border-collapse text-left">
            <thead>
              <tr>
                <th className="w-40 border-b border-slate-200 bg-slate-50 p-4 text-xs font-black uppercase tracking-wider text-slate-500 dark:border-slate-800 dark:bg-slate-950/60 dark:text-slate-400">Critério</th>
                {items.map((item) => (
                  <th key={item.id} className="min-w-[240px] border-b border-l border-slate-200 p-4 align-top dark:border-slate-800">
                    <div className="overflow-hidden rounded-xl bg-slate-100 dark:bg-slate-800">
                      {item.imagem ? (
                        <img src={item.imagem} alt="" className="h-36 w-full object-cover" />
                      ) : (
                        <div className="flex h-36 items-center justify-center text-xs font-bold text-slate-400">Sem fotografia</div>
                      )}
                    </div>
                    <Link to={'/anuncio/' + item.id} className="mt-4 block text-base font-black leading-6 text-slate-950 no-underline hover:text-teal-700 dark:text-white dark:hover:text-teal-300">
                      {item.titulo}
                    </Link>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              <tr>
                <th className="border-b border-slate-200 bg-slate-50 p-4 text-xs font-black uppercase tracking-wider text-slate-500 dark:border-slate-800 dark:bg-slate-950/60 dark:text-slate-400">Preço</th>
                {items.map((item) => <td key={item.id} className="border-b border-l border-slate-200 p-4 text-xl font-black text-teal-700 dark:border-slate-800 dark:text-teal-300">{formatPrice(item.preco)}</td>)}
              </tr>
              <tr>
                <th className="border-b border-slate-200 bg-slate-50 p-4 text-xs font-black uppercase tracking-wider text-slate-500 dark:border-slate-800 dark:bg-slate-950/60 dark:text-slate-400">Categoria</th>
                {items.map((item) => <td key={item.id} className="border-b border-l border-slate-200 p-4 text-sm font-bold dark:border-slate-800">{item.tipo === 'carro' ? 'Automóvel' : 'Imóvel'}</td>)}
              </tr>
              <tr>
                <th className="border-b border-slate-200 bg-slate-50 p-4 text-xs font-black uppercase tracking-wider text-slate-500 dark:border-slate-800 dark:bg-slate-950/60 dark:text-slate-400">Ano / Área</th>
                {items.map((item) => <td key={item.id} className="border-b border-l border-slate-200 p-4 text-sm font-bold dark:border-slate-800">{item.anoArea}</td>)}
              </tr>
              <tr>
                <th className="border-b border-slate-200 bg-slate-50 p-4 text-xs font-black uppercase tracking-wider text-slate-500 dark:border-slate-800 dark:bg-slate-950/60 dark:text-slate-400">Localização</th>
                {items.map((item) => <td key={item.id} className="border-b border-l border-slate-200 p-4 text-sm text-slate-600 dark:border-slate-800 dark:text-slate-300">{item.localizacao}</td>)}
              </tr>
              <tr>
                <th className="bg-slate-50 p-4 text-xs font-black uppercase tracking-wider text-slate-500 dark:bg-slate-950/60 dark:text-slate-400">Ações</th>
                {items.map((item) => (
                  <td key={item.id} className="border-l border-slate-200 p-4 dark:border-slate-800">
                    <div className="flex gap-2">
                      <Link to={'/anuncio/' + item.id} className="rounded-lg bg-slate-950 px-3 py-2 text-xs font-extrabold text-white no-underline hover:bg-slate-800 dark:bg-teal-400 dark:text-slate-950 dark:hover:bg-teal-300">Ver anúncio</Link>
                      <button type="button" onClick={() => remover(item.id)} className="rounded-lg border border-slate-300 bg-white px-3 py-2 text-xs font-extrabold text-slate-700 hover:bg-slate-50 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-200 dark:hover:bg-slate-800">Remover</button>
                    </div>
                  </td>
                ))}
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    </main>
  );
}
